"""Small, read-only resource and collaborator-note monitor for this project."""
from pathlib import Path
import argparse, datetime as dt, hashlib, json, os, shutil, subprocess, time
import psutil

ROOT = Path(__file__).resolve().parents[1]
NOTES = ROOT.parent / 'shared_notes'
OUT = ROOT / 'monitoring'

def utc():
    return dt.datetime.now(dt.timezone.utc).isoformat()

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--interval', type=float, default=20)
    args = parser.parse_args()
    OUT.mkdir(exist_ok=True)
    start_file = OUT / 'start.json'
    if not start_file.exists():
        start_file.write_text(json.dumps({'author': 'Codex-root', 'started_utc': utc(),
            'started_unix': time.time(), 'pid': os.getpid()}, indent=2)+'\n')
    start = json.loads(start_file.read_text())['started_unix']
    known = {}
    gpu_tool = shutil.which('nvidia-smi')
    gpu_last = 0
    gpu = None
    psutil.cpu_percent(None)
    while True:
        now = time.time()
        if gpu_tool and now-gpu_last >= 60:
            try:
                info = subprocess.run([gpu_tool,'--query-gpu=name,memory.total,memory.used,utilization.gpu,power.draw','--format=csv,noheader,nounits'],capture_output=True,text=True,timeout=3)
                gpu = {'sampled_utc':utc(),'fields':['name','memory_total_MiB','memory_used_MiB','utilization_percent','power_W'],'csv':info.stdout.strip(),'returncode':info.returncode}
            except (OSError,subprocess.TimeoutExpired) as exc:
                gpu = {'sampled_utc':utc(),'error':str(exc)}
            gpu_last = now
        processes = []
        for p in psutil.process_iter(['pid','cmdline','memory_info','cpu_times','num_threads']):
            try:
                cmd = ' '.join(p.info['cmdline'] or [])
                if str(ROOT) not in cmd or p.pid == os.getpid():
                    continue
                cpu = p.info['cpu_times']
                processes.append({'pid': p.pid, 'rss_mb': p.info['memory_info'].rss/2**20,
                    'cpu_user_s': cpu.user, 'cpu_system_s': cpu.system,
                    'threads': p.info['num_threads'], 'command': cmd[:450]})
            except (psutil.Error, OSError):
                pass
        changes = []
        for p in sorted(NOTES.glob('*')):
            if p.is_file():
                stat = p.stat()
                signature = (stat.st_size, stat.st_mtime_ns)
                if known.get(p.name) != signature:
                    changes.append({'file': p.name, 'bytes': stat.st_size,
                        'mtime_utc': dt.datetime.fromtimestamp(stat.st_mtime, dt.timezone.utc).isoformat()})
                    known[p.name] = signature
        progress_path = OUT / 'progress.json'
        progress = json.loads(progress_path.read_text()) if progress_path.exists() else {}
        row = {'utc': utc(), 'elapsed_s': now-start, 'system_cpu_percent': psutil.cpu_percent(None),
            'available_memory_mb': psutil.virtual_memory().available/2**20,
            'project_processes': processes, 'new_or_changed_notes': changes,
            'progress': progress, 'gpu':gpu}
        with (OUT/'resources.jsonl').open('a') as stream:
            stream.write(json.dumps(row)+'\n')
        (OUT/'latest.json').write_text(json.dumps(row, indent=2)+'\n')
        if (OUT/'STOP').exists():
            break
        time.sleep(args.interval)

if __name__ == '__main__':
    main()
